import { ReactNode, FC } from 'react';

interface ListItemProps {
    /** 标题 */
    title?: ReactNode;
    /** 描述 */
    description?: ReactNode;
    /** 左侧额外内容 */
    prefix?: ReactNode;
    /** 右侧额外内容 */
    extra?: ReactNode;
    /** 是否显示箭头 */
    arrow?: boolean;
    /** 是否禁用 */
    disabled?: boolean;
    /** 是否可点击 */
    clickable?: boolean;
    /** 点击回调 */
    onClick?: () => void;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface ListProps {
    /** 列表头部 */
    header?: ReactNode;
    /** 列表尾部 */
    footer?: ReactNode;
    /** 是否显示分割线 */
    bordered?: boolean;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const ListItem: FC<ListItemProps>;
type ListComponent = FC<ListProps> & {
    Item: FC<ListItemProps>;
};
declare const List: ListComponent;

export { List, ListItem, List as default };
export type { ListItemProps, ListProps };
